import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

class LoadingPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = { width: window.outerWidth, height: window.outerHeight };
  }

  componentDidMount() {
    window.addEventListener("resize", () =>
      this.setState({ width: window.outerWidth, height: window.outerHeight })
    );
  }

  render() {
    const width = 40;

    const spacing = width + 10;
    const jumpHeight = 200;

    const numPoints = 14;

    const circleRingLeft = _.times(numPoints, n => {
      const x = n * spacing;

      return (
        <div
          className="circle"
          style={{
            offsetPath: `path("M ${x - numPoints * spacing - width},${
              -275 + jumpHeight / 2
            } l ${0},-${jumpHeight}")`,
            animationDelay: `-${Math.random() * 100}s`
          }}
        ></div>
      );
    });

    const circleRingRight = _.times(numPoints, n => {
      const x = n * spacing;

      return (
        <div
          className="circle"
          style={{
            offsetPath: `path("M ${x + 125},${
              -275 + jumpHeight / 2
            } l ${0},-${jumpHeight}")`,
            animationDelay: `-${Math.random() * 2}s`
          }}
        ></div>
      );
    });

    return (
      <div className="loading-page-wrapper">
        <h1 className="loading-text-wrapper montserrat-light">loading</h1>
        {circleRingLeft}
        {circleRingRight}
      </div>
    );
  }
}

export default LoadingPage;
